const $=s=>document.querySelector(s), app=$('#app');
const state={token:localStorage.getItem('rsr_token')||'',user:JSON.parse(localStorage.getItem('rsr_user')||'null'),config:null,orders:[],messages:[],vouches:[],page:'dashboard',method:'covered_tax',robloxUser:null,gamepasses:[],game:null,adminChatUserId:'',chatOrderId:'',chatDraft:'',chatSending:false,giftItems:[{name:'',quantity:1,itemLink:''}],giftRecipientUser:null,ordersLoading:false,ordersRetryTimer:null,installPrompt:null,realtimeTimer:null,lastOrderFingerprint:'',lastChatFingerprint:'',notificationPermission:typeof Notification!=='undefined'?Notification.permission:'unsupported'};
const money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(n||0));
const num=n=>Number(n||0).toLocaleString();
const methodName=m=>({covered_tax:'Covered Tax',not_covered_tax:'Not Covered Tax',instant_send:'Instant Send',gifting:'Gifting'})[m]||m;
const contactFacebook=()=>state.config?.facebookUrl||'https://www.facebook.com/profile.php?id=61592793360824';
const contactEmail=()=>state.config?.contactEmail||'reckshopemergencycontact@gmail.com';
function applyTheme(theme){const value=theme==='light'?'light':'dark';document.documentElement.dataset.theme=value;localStorage.setItem('rsr_theme',value);document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.textContent=value==='dark'?'☀️ Light mode':'🌙 Dark mode')}
function notifyUser(title,body,tag='rsr-update'){if(!('Notification'in window)||Notification.permission!=='granted')return;try{if(navigator.serviceWorker?.controller)navigator.serviceWorker.ready.then(r=>r.showNotification(title,{body,icon:'/icon-192.png',badge:'/icon-192.png',tag,renotify:true,data:{url:location.href}}));else new Notification(title,{body,icon:'/icon-192.png',tag})}catch{}}
async function enableNotifications(){if(!('Notification'in window))return toast('Notifications are not supported on this device.','error');const permission=await Notification.requestPermission();state.notificationPermission=permission;if(permission==='granted'){toast('Notifications enabled.');notifyUser('RSR Shop notifications enabled','You will receive order and support updates while the app is active.','rsr-enabled')}else toast('Notifications were not enabled. You can change this in browser settings.','error');renderPage()}
function orderFingerprint(list){return list.map(o=>`${o.id}:${o.status}:${o.updatedAt||o.createdAt}`).sort().join('|')}
function chatFingerprint(list){return list.map(m=>m.id).sort().join('|')}
async function realtimeTick(){if(!state.user||!state.token||document.hidden)return;try{const [od,cd]=await Promise.all([api('/api/orders'),api('/api/chat')]);const of=orderFingerprint(od.orders||[]),cf=chatFingerprint(cd.messages||[]);if(state.lastOrderFingerprint&&of!==state.lastOrderFingerprint){const newest=(od.orders||[]).slice().sort((a,b)=>new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt))[0];notifyUser(state.user.role==='admin'?'New order activity':'Order updated',newest?`${newest.orderNo}: ${newest.status}`:'Your orders changed','rsr-order-update')}
if(state.lastChatFingerprint&&cf!==state.lastChatFingerprint){const latest=(cd.messages||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];if(latest&&latest.senderId!==state.user.id)notifyUser('New support message',`${latest.senderName}: ${latest.text.slice(0,100)}`,'rsr-chat-update')}
state.orders=od.orders||state.orders;state.messages=cd.messages||state.messages;state.lastOrderFingerprint=of;state.lastChatFingerprint=cf;}catch{}}
function startRealtimeWatcher(){clearInterval(state.realtimeTimer);realtimeTick();state.realtimeTimer=setInterval(realtimeTick,8000)}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function saveSession(data){state.token=data.token;state.user=data.user;localStorage.setItem('rsr_token',data.token);localStorage.setItem('rsr_user',JSON.stringify(data.user))}
function clearSession(){clearInterval(state.realtimeTimer);state.token='';state.user=null;localStorage.removeItem('rsr_token');localStorage.removeItem('rsr_user')}
async function api(path,opt={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const res=await fetch(path,{...opt,signal:controller.signal,headers:{'content-type':'application/json',...(state.token?{authorization:`Bearer ${state.token}`}:{}) ,...(opt.headers||{})},cache:'no-store'});let data={};try{data=await res.json()}catch{}if(!res.ok){if(res.status===401&&path!='/api/auth/login'){clearSession();renderAuth('Your session expired. Please sign in again.')}throw new Error(data.error||`Request failed (${res.status})`)}return data}catch(e){if(e.name==='AbortError')throw new Error('The server took too long to respond. Please try again.');throw e}finally{clearTimeout(timeout)}}
function toast(msg,type='good'){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.style='position:fixed;right:18px;top:18px;z-index:100;max-width:360px';document.body.appendChild(t)}t.innerHTML=`<div class="notice ${type==='error'?'error':'good'}">${esc(msg)}</div>`;setTimeout(()=>t.innerHTML='',3500)}
function renderAuth(message=''){app.innerHTML=`<main class="auth-wrap"><section class="card auth-card"><h1 class="brand"><span>RSR SHOP MARKETPLACE</span></h1><p class="muted">Secure Robux orders, verified receipts, and direct admin support.</p>${message?`<div class="notice error">${esc(message)}</div>`:''}<div class="auth-tabs"><button id="tab-login" class="active">Sign In</button><button id="tab-register">Create Account</button></div><form id="auth-form" class="stack"><div id="name-wrap" class="field hidden"><label>Full name</label><input id="auth-name" class="input" autocomplete="name"></div><div class="field"><label>Email</label><input id="auth-email" class="input" type="email" autocomplete="email" required></div><div class="field"><label>Password</label><input id="auth-password" class="input" type="password" autocomplete="current-password" minlength="8" required></div><div id="confirm-wrap" class="field hidden"><label>Confirm password</label><input id="auth-confirm" class="input" type="password"></div><div id="auth-error"></div><button id="auth-submit" class="btn" type="submit">Sign In</button></form><button id="install-auth" class="btn secondary install hidden">Install RSR Shop App</button></section></main>`;
let mode='login';const setMode=m=>{mode=m;$('#tab-login').classList.toggle('active',m==='login');$('#tab-register').classList.toggle('active',m==='register');$('#name-wrap').classList.toggle('hidden',m!=='register');$('#confirm-wrap').classList.toggle('hidden',m!=='register');$('#auth-submit').textContent=m==='login'?'Sign In':'Create Account';$('#auth-password').autocomplete=m==='login'?'current-password':'new-password';$('#auth-error').innerHTML=''};$('#tab-login').onclick=()=>setMode('login');$('#tab-register').onclick=()=>setMode('register');$('#auth-form').onsubmit=async e=>{e.preventDefault();const btn=$('#auth-submit');btn.disabled=true;btn.textContent=mode==='login'?'Signing in…':'Creating account…';$('#auth-error').innerHTML='';try{const email=$('#auth-email').value.trim(),password=$('#auth-password').value;if(mode==='register'){if(password!==$('#auth-confirm').value)throw new Error('Passwords do not match.');const data=await api('/api/auth/register',{method:'POST',body:JSON.stringify({name:$('#auth-name').value,email,password})});saveSession(data)}else{const data=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});saveSession(data)}await enterApp()}catch(err){$('#auth-error').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;btn.disabled=false;btn.textContent=mode==='login'?'Sign In':'Create Account'}};updateInstallButton('#install-auth')}
function navButtons(){const admin=state.user.role==='admin';if(admin)return `<div class="nav-label">ADMIN APP</div><button data-page="dashboard" data-icon="📈">Sales Dashboard</button><button data-page="orders" data-icon="📋">Manage Orders</button><button data-page="chat" data-icon="💬">Live Support</button><button data-page="analytics" data-icon="📊">Analytics</button><button data-page="settings" data-icon="💰">Rates & Settings</button><button data-page="tutorials" data-icon="🎥">Tutorial Videos</button><button data-page="adminVouches" data-icon="⭐">Vouch Review</button><button data-page="notifications" data-icon="🔔">Notifications</button><button data-page="profile" data-icon="👤">Admin Profile</button>`;return `<div class="nav-label">CUSTOMER APP</div><button data-page="order" data-icon="🛒">Shop</button><button data-page="orders" data-icon="📦">My Orders</button><button data-page="chat" data-icon="💬">Live Chat</button><button data-page="notifications" data-icon="🔔">Notifications</button><button data-page="profile" data-icon="👤">Profile</button><button data-page="vouches" data-icon="⭐">Vouches</button><button data-page="tutorials" data-icon="📖">Tutorials</button>`}
function shell(content,title){app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span>RSR SHOP</span><small>Marketplace App</small></div><nav class="nav">${navButtons()}</nav><div class="sidebar-contact"><a href="${esc(contactFacebook())}" target="_blank" rel="noopener">Facebook Support</a><a href="mailto:${esc(contactEmail())}">${esc(contactEmail())}</a></div><div class="sidebar-foot"><button data-theme-toggle class="btn secondary theme-toggle">☀️ Light mode</button><button id="logout" class="btn secondary">Sign Out</button></div></aside><main class="main"><header class="topbar"><button id="mobile-menu" class="mobile-menu" aria-label="Open menu">☰</button><div class="topbar-title"><h1>${esc(title)}</h1><div class="muted">${esc(state.config?.announcement||'')}</div></div><div class="topbar-actions"><button id="top-notify" class="icon-action" title="Notifications">🔔</button><div class="user-pill">${esc(state.user.name)} · ${esc(state.user.role)}</div></div></header><section id="content">${content}</section><footer class="app-footer"><span>Need help?</span><a href="${esc(contactFacebook())}" target="_blank" rel="noopener">Facebook</a><a href="mailto:${esc(contactEmail())}">${esc(contactEmail())}</a></footer></main><nav class="mobile-bottom">${state.user.role==='admin'?`<button data-page="dashboard">📈<span>Dashboard</span></button><button data-page="orders">📋<span>Orders</span></button><button data-page="chat">💬<span>Support</span></button><button data-page="settings">⚙️<span>Settings</span></button>`:`<button data-page="order">🛒<span>Shop</span></button><button data-page="orders">📦<span>Orders</span></button><button data-page="chat">💬<span>Chat</span></button><button data-page="profile">👤<span>Profile</span></button>`}</nav><div id="sidebar-overlay" class="sidebar-overlay"></div></div>`;document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.onclick=()=>{if(b.dataset.page==='chat')state.chatOrderId='';state.page=b.dataset.page;renderPage()}});$('#logout').onclick=()=>{clearSession();renderAuth()};document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=()=>applyTheme(document.documentElement.dataset.theme==='light'?'dark':'light'));applyTheme(localStorage.getItem('rsr_theme')||'dark');$('#top-notify').onclick=()=>{state.page='notifications';renderPage()};const side=$('#sidebar'),overlay=$('#sidebar-overlay');$('#mobile-menu').onclick=()=>{side.classList.add('open');overlay.classList.add('show')};overlay.onclick=()=>{side.classList.remove('open');overlay.classList.remove('show')}}
async function enterApp(){try{const [me,config]=await Promise.all([api('/api/me'),api('/api/config')]);state.user=me.user;state.config=config;localStorage.setItem('rsr_user',JSON.stringify(me.user));state.page=state.user.role==='admin'?'dashboard':'order';await refreshCore();state.lastOrderFingerprint=orderFingerprint(state.orders);renderPage();startRealtimeWatcher()}catch(e){if(state.token)renderAuth(e.message)}}
async function refreshCore(){const jobs=[api('/api/orders').then(d=>state.orders=d.orders),api('/api/vouches').then(d=>state.vouches=d.vouches)];await Promise.allSettled(jobs)}
function renderPage(){if(!state.user)return renderAuth();if(state.page==='dashboard')return renderDashboard();if(state.page==='order')return renderOrder();if(state.page==='orders')return renderOrders();if(state.page==='chat')return renderChat();if(state.page==='vouches')return renderVouches();if(state.page==='tutorials')return renderTutorials();if(state.page==='notifications')return renderNotifications();if(state.page==='profile')return renderProfile();if(state.page==='analytics')return renderAnalytics();if(state.page==='settings')return renderSettings();if(state.page==='adminVouches')return renderAdminVouches();state.page=state.user.role==='admin'?'dashboard':'order';renderPage()}
function safeTutorialUrl(value){try{const u=new URL(String(value||''));return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
function tutorialCard(title,url,description){const safe=safeTutorialUrl(url);return `<article class="tutorial-card"><div class="tutorial-play">▶</div><div><b>${esc(title)}</b><p class="muted">${esc(description)}</p>${safe?`<a class="btn secondary" href="${esc(safe)}" target="_blank" rel="noopener">Watch Tutorial</a>`:'<span class="muted">Tutorial coming soon.</span>'}</div></article>`}
function renderDashboard(){const own=state.user.role==='admin'?state.orders:state.orders.filter(o=>o.userId===state.user.id),completed=own.filter(o=>o.status==='Completed'),pending=own.filter(o=>!['Completed','Cancelled'].includes(o.status)),robux=completed.reduce((s,o)=>s+o.robuxAmount,0),revenue=completed.reduce((s,o)=>s+o.totalPhp,0);shell(`<div class="grid grid-4"><div class="card stat"><span class="muted">Total orders</span><b>${num(own.length)}</b></div><div class="card stat"><span class="muted">Active orders</span><b>${num(pending.length)}</b></div><div class="card stat"><span class="muted">Completed Robux</span><b>R$ ${num(robux)}</b></div><div class="card stat"><span class="muted">${state.user.role==='admin'?'Completed revenue':'Completed spending'}</span><b>${money(revenue)}</b></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><h2>Quick order</h2><p class="muted">Verify your Roblox profile, let the shop calculate the exact payment, then upload a clear receipt.</p><button id="start-order" class="btn">Create New Order</button></div><div class="card"><h2>Install the app</h2><p class="muted">Install RSR Shop on Android, Windows, macOS, Chromebook, iPhone, or iPad.</p><button id="install-main" class="btn secondary">Install App</button></div></div><div class="card tutorial-center" style="margin-top:16px"><div class="section-head"><div><small class="eyebrow">HELP CENTER</small><h2>Video tutorials</h2><p class="muted">Watch the official shop guides before placing an order.</p></div></div><div class="grid grid-2">${tutorialCard('How to order',state.config.tutorials?.orderUrl,'Complete checkout guide')}${tutorialCard('How to create a gamepass',state.config.tutorials?.gamepassUrl,'Required for Covered Tax and Not Covered Tax')}</div></div><div class="card" style="margin-top:16px"><h2>Why customers trust RSR Shop</h2><div class="grid grid-3"><div><b>Verified recipient</b><p class="muted">Roblox profile is confirmed before checkout.</p></div><div><b>Receipt review</b><p class="muted">Admin checks the uploaded payment proof before processing.</p></div><div><b>Direct support</b><p class="muted">Customer and admin can chat inside the shop.</p></div></div></div>`,'Dashboard');$('#start-order').onclick=()=>{state.page='order';renderPage()};updateInstallButton('#install-main')}
function calculate(){const amount=Math.max(0,Math.floor(Number($('#robux-amount')?.value||0))),rate=Number(state.config.rates[state.method]||0),required=state.method==='covered_tax'?Math.ceil(amount/.7):(state.method==='not_covered_tax'?amount:0);$('#sum-receive')&&( $('#sum-receive').textContent=`R$ ${num(amount)}`,$('#sum-required').textContent=required?`R$ ${num(required)}`:'Not required',$('#sum-pay').textContent=money(amount*rate));return{amount,required,totalPhp:amount*rate}}
function renderOrder(){state.gamepasses=[];state.robloxUser=null;state.game=null;state.giftItems=[{name:'',quantity:1,itemLink:''}];state.giftRecipientUser=null;const methods=[
['covered_tax','🛡️','Covered Tax','Receive the exact Robux you ordered. The required gamepass price is automatically increased to include Roblox’s marketplace fee.','Best when you want an exact final payout. Example: 1,000 received requires a 1,429 gamepass.'],
['not_covered_tax','🏷️','Not Covered Tax','The gamepass price matches the amount you buy, then Roblox removes its marketplace fee before the seller receives it.','Example: a 1,000 gamepass normally gives about 700 Robux after the fee.'],
['instant_send','⚡','Instant Send','A faster stock-based delivery method when the shop has eligible Robux available. Availability and account limits are checked by the admin.','Never share your Roblox password or verification code. Delivery speed depends on stock and Roblox limits.'],
['gifting','🎁','Gifting','Delivery is coordinated using your verified Roblox account and verified game. The admin may contact you through Live Chat for in-game instructions.','Double-check the account and game before submitting. Completed digital deliveries may not be reversible.']
];shell(`<div class="stepbar"><span class="step active">1 Method</span><span class="step">2 Account & details</span><span class="step">3 Payment</span><span class="step">4 Submit</span></div><div class="card"><div class="section-head"><div><h2>Choose an order method</h2><p class="muted">Select the option that matches how you want the Robux delivered. Read the rule on each card before continuing.</p></div></div><div class="method-grid enhanced">${methods.map(([id,icon,n,d,r])=>`<button class="method ${state.method===id?'selected':''}" data-method="${id}" ${state.config.methods[id]?'':'disabled'}><span class="method-icon">${icon}</span><span class="method-title">${n}</span><span class="method-desc">${d}</span><span class="method-rule"><b>Important:</b> ${r}</span><span class="method-rate">Current rate: ${money(Number(state.config.rates[id]||0)*100)} per 100 Robux</span>${state.config.methods[id]?'':'<span class="method-unavailable">Currently unavailable</span>'}</button>`).join('')}</div></div><form id="order-form" class="stack" style="margin-top:16px"><div class="card"><h2>Verify Roblox account</h2><div class="grid grid-2"><div class="field"><label>Username, User ID, or profile link</label><input id="roblox-input" class="input" placeholder="CraftReck or Roblox profile URL"></div><div style="align-self:end"><button id="verify-user" type="button" class="btn">Verify Account</button></div></div><div id="verified-user" style="margin-top:14px"></div></div><div class="card"><h2>Order amount</h2><div class="grid grid-2"><div class="field"><label>Robux to buy</label><input id="robux-amount" class="input" type="number" min="${state.config.minRobux}" max="${state.config.maxRobux}" value="1000" required></div><div class="summary"><div><span class="muted">Receive</span><b id="sum-receive"></b></div><div><span class="muted">Required gamepass</span><b id="sum-required"></b></div><div><span class="muted">Amount to pay</span><b id="sum-pay"></b></div></div></div><div id="method-extra" style="margin-top:14px"></div></div><div class="card"><h2>Payment</h2><div class="grid grid-2"><label class="card"><input type="radio" name="payment" value="GCash" checked> <b>GCash</b><br><img class="qr" src="/gcash-qr.png" alt="GCash QR"></label><label class="card"><input type="radio" name="payment" value="GoTyme"> <b>GoTyme / InstaPay</b><br><img class="qr" src="/gotyme-qr.png" alt="GoTyme QR"></label></div><div class="field" style="margin-top:14px"><label>Upload clear payment receipt (image only)</label><input id="receipt" class="input" type="file" accept="image/png,image/jpeg,image/webp" required><small class="muted">Upload the original, readable receipt. The admin will view it when reviewing the order.</small></div></div><div id="checkout-readiness"></div><button id="submit-order" class="btn" type="submit">Complete Required Details</button></form>`,'Create Order');document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{state.method=b.dataset.method;document.querySelectorAll('[data-method]').forEach(x=>x.classList.toggle('selected',x===b));state.gamepasses=[];state.game=null;renderMethodExtra();calculate();updateSubmitState()});$('#robux-amount').oninput=()=>{calculate();if(['covered_tax','not_covered_tax'].includes(state.method))renderPasses();updateSubmitState()};$('#verify-user').onclick=verifyUser;$('#order-form').onsubmit=submitOrder;$('#receipt').onchange=updateSubmitState;renderMethodExtra();calculate();updateSubmitState()}
function renderMethodExtra(){
  const box=$('#method-extra');
  if(['covered_tax','not_covered_tax'].includes(state.method)){
    const isCT=state.method==='covered_tax';
    box.innerHTML=`<section class="method-workspace"><div class="method-workspace-head"><div><span class="eyebrow">${isCT?'🛡️ COVERED TAX':'🏷️ NOT COVERED TAX'}</span><h3>Gamepass Inventory</h3><p class="muted">No Roblox game link is required. Verify the Roblox username above, then add one or more gamepass links. We check each gamepass name, owner, and current price.</p></div><div class="required-total"><small>Required total</small><b id="inventory-required">R$ 0</b></div></div><div class="gamepass-add"><input id="pass-input" class="input" placeholder="Paste a Roblox gamepass link or gamepass ID"><button id="verify-pass" type="button" class="btn secondary">Verify & Add</button></div><div id="pass-list" class="gamepass-inventory"></div></section>`;
    $('#verify-pass').onclick=verifyPass;renderPasses();
  }else if(state.method==='gifting'){
    if(!Array.isArray(state.giftItems)||!state.giftItems.length)state.giftItems=[{name:'',quantity:1,itemLink:''}];
    box.innerHTML=`<section class="method-workspace gifting-workspace"><div class="method-workspace-head"><div><span class="eyebrow">🎁 GIFTING ORDER</span><h3>Gift delivery details</h3><p class="muted">Complete every required field. The order cannot be submitted until the recipient, items, and game are verified.</p></div><div class="required-total"><small>Delivery type</small><b>In-game gift</b></div></div><div class="gift-recipient-card"><div class="field"><label>Roblox username receiving the gift <b class="required-mark">Required</b></label><div class="verify-inline"><input id="gift-recipient" class="input" placeholder="Exact Roblox username" value="${esc(state.giftRecipientUser?.name||state.robloxUser?.name||'')}"><button id="verify-gift-recipient" type="button" class="btn secondary">Verify Recipient</button></div><small class="muted">This can be different from the account placing the order.</small></div><div id="gift-recipient-result"></div></div><div class="gift-items-head"><div><h3>Items to deliver</h3><p class="muted">List the exact item name, quantity, and optional item link or ID.</p></div><button id="add-gift-item" type="button" class="btn secondary">＋ Add Another Item</button></div><div id="gift-items" class="gift-items-list"></div><div class="field"><label>Delivery instructions</label><textarea id="gift-notes" class="input" rows="3" placeholder="Private server link, meeting location, preferred time, or other instructions"></textarea></div><div class="game-verify-block"><h3>Verify the Roblox experience</h3><p class="muted">Paste the game link or Place ID where the item will be delivered.</p><div class="grid grid-2"><input id="game-input" class="input" placeholder="Roblox game link or Place ID"><button id="verify-game" type="button" class="btn secondary">Verify Game</button></div><div id="game-result" style="margin-top:10px"></div></div></section>`;
    renderGiftItems();$('#add-gift-item').onclick=()=>{captureGiftItems();state.giftItems.push({name:'',quantity:1,itemLink:''});renderGiftItems();updateSubmitState()};$('#verify-game').onclick=verifyGame;$('#verify-gift-recipient').onclick=verifyGiftRecipient;$('#gift-recipient').oninput=()=>{state.giftRecipientUser=null;$('#gift-recipient-result').innerHTML='';updateSubmitState()};$('#gift-notes').oninput=updateSubmitState;
  }else box.innerHTML=`<div class="notice"><b>⚡ Instant Send</b><p>The verified Roblox account above will receive the order. No gamepass or game link is required. Availability is confirmed by the admin.</p></div>`;
}
function captureGiftItems(){document.querySelectorAll('[data-gift-row]').forEach((row,i)=>{if(!state.giftItems[i])state.giftItems[i]={name:'',quantity:1,itemLink:''};state.giftItems[i].name=row.querySelector('[data-gift-name]')?.value||'';state.giftItems[i].quantity=Math.max(1,Number(row.querySelector('[data-gift-qty]')?.value||1));state.giftItems[i].itemLink=row.querySelector('[data-gift-link]')?.value||''})}
function renderGiftItems(){const box=$('#gift-items');if(!box)return;box.innerHTML=state.giftItems.map((item,i)=>`<div class="gift-item-row professional" data-gift-row="${i}"><div class="field"><label>Item ${i+1} name <b class="required-mark">Required</b></label><input class="input" data-gift-name value="${esc(item.name||'')}" placeholder="Example: VIP Pass, Pet, Sword, Bundle"></div><div class="field"><label>Item link or ID <span class="muted">Optional</span></label><input class="input" data-gift-link value="${esc(item.itemLink||'')}" placeholder="Marketplace link, item ID, or game item name"></div><div class="field gift-qty"><label>Quantity</label><input class="input" data-gift-qty type="number" min="1" max="999" value="${Math.max(1,Number(item.quantity||1))}"></div>${state.giftItems.length>1?`<button class="btn danger gift-remove" type="button" data-remove-gift="${i}">Remove</button>`:''}</div>`).join('');box.querySelectorAll('input').forEach(el=>el.oninput=()=>{captureGiftItems();updateSubmitState()});box.querySelectorAll('[data-remove-gift]').forEach(b=>b.onclick=()=>{captureGiftItems();state.giftItems.splice(Number(b.dataset.removeGift),1);renderGiftItems();updateSubmitState()})}
async function verifyGiftRecipient(){const input=$('#gift-recipient'),btn=$('#verify-gift-recipient');btn.disabled=true;btn.textContent='Verifying…';try{const d=await api('/api/roblox/user',{method:'POST',body:JSON.stringify({input:input.value})});state.giftRecipientUser=d.user;input.value=d.user.name;$('#gift-recipient-result').innerHTML=`<div class="notice good profile-card compact"><img class="avatar" src="${esc(d.user.avatar||'/icon.svg')}"><div><b>Verified gift recipient</b><div>${esc(d.user.displayName)} · @${esc(d.user.name)}</div><small class="muted">User ID: ${d.user.id}</small></div><a class="btn secondary" target="_blank" href="${esc(d.user.profileUrl)}">View Profile</a></div>`;updateSubmitState()}catch(e){state.giftRecipientUser=null;toast(e.message,'error');updateSubmitState()}finally{btn.disabled=false;btn.textContent='Verify Recipient'}}

async function verifyUser(){const btn=$('#verify-user');btn.disabled=true;btn.textContent='Verifying…';try{const d=await api('/api/roblox/user',{method:'POST',body:JSON.stringify({input:$('#roblox-input').value})});state.robloxUser=d.user;if(state.method==='gifting'&&$('#gift-recipient')&&!$('#gift-recipient').value.trim())$('#gift-recipient').value=d.user.name;$('#verified-user').innerHTML=`<div class="notice good profile-card"><img class="avatar" src="${esc(d.user.avatar||'/icon.svg')}"><div><b>Verified Roblox account</b><div>${esc(d.user.displayName)} · @${esc(d.user.name)}</div><small class="muted">User ID: ${d.user.id}</small></div><a class="btn secondary" target="_blank" href="${esc(d.user.profileUrl)}">View Profile</a></div>`}catch(e){toast(e.message,'error')}finally{btn.disabled=false;btn.textContent='Verify Account';updateSubmitState()}}
async function verifyPass(){const btn=$('#verify-pass'),input=$('#pass-input');if(!input.value.trim())return toast('Paste a gamepass link or ID.','error');btn.disabled=true;btn.textContent='Checking Roblox…';try{const d=await api('/api/roblox/gamepass',{method:'POST',body:JSON.stringify({input:input.value})});if(!d.gamepass.isForSale)throw new Error('This gamepass is not currently for sale. Turn on Item for Sale in Roblox first.');if(!Number(d.gamepass.price))throw new Error('This gamepass does not have a Robux price. Set its price in Roblox first.');if(!state.gamepasses.some(p=>p.id===d.gamepass.id))state.gamepasses.push(d.gamepass);input.value='';renderPasses();toast(`Verified ${d.gamepass.name} for R$ ${num(d.gamepass.price)}.`);updateSubmitState()}catch(e){toast(e.message,'error')}finally{btn.disabled=false;btn.textContent='Verify & Add'}}
function renderPasses(){const list=$('#pass-list');if(!list)return;const c=calculate(),total=state.gamepasses.reduce((sum,p)=>sum+Number(p.price||0),0),difference=c.required-total,remaining=Math.max(0,difference),over=Math.max(0,-difference);const req=$('#inventory-required');if(req)req.textContent=`R$ ${num(c.required)}`;list.innerHTML=`<div class="inventory-summary"><span><small>Verified total</small><b>R$ ${num(total)}</b></span><span><small>Required total</small><b>R$ ${num(c.required)}</b></span><span class="${difference===0?'inventory-ok':'inventory-warn'}"><small>${difference===0?'Status':difference>0?'Still needed':'Too high by'}</small><b>${difference===0?'✓ Exact price match':`R$ ${num(difference>0?remaining:over)}`}</b></span></div>${state.gamepasses.length?`<div class="inventory-list">${state.gamepasses.map((p,i)=>`<article class="inventory-item professional">${p.thumbnail?`<img class="pass-thumb" src="${esc(p.thumbnail)}" alt="Gamepass">`:''}<div><small>Verified gamepass ${i+1}</small><b>${esc(p.name)}</b><span>Creator: ${esc(p.creator||'Unknown')} · ID ${p.id}</span><a href="${esc(p.url)}" target="_blank" rel="noopener">Open on Roblox</a></div><strong>R$ ${num(p.price)}</strong><button type="button" class="btn danger" data-remove-pass="${i}">Remove</button></article>`).join('')}</div>`:`<div class="inventory-empty"><b>No gamepasses verified</b><p>Paste the full Roblox gamepass link, then press Verify & Add.</p></div>`}`;document.querySelectorAll('[data-remove-pass]').forEach(b=>b.onclick=()=>{state.gamepasses.splice(Number(b.dataset.removePass),1);renderPasses();updateSubmitState()});updateSubmitState()}


async function verifyGame(){try{const d=await api('/api/roblox/game',{method:'POST',body:JSON.stringify({input:$('#game-input').value})});state.game=d.game;$('#game-result').innerHTML=`<div class="notice good game-verified">${d.game.icon?`<img src="${esc(d.game.icon)}" alt="Game icon">`:''}<div><b>Verified game:</b> ${esc(d.game.name)}<br><span>Place ID ${d.game.placeId} · Creator ${esc(d.game.creatorName)}</span></div></div>`}catch(e){state.game=null;toast(e.message,'error')}finally{updateSubmitState()}}
function fileData(file){return new Promise((resolve,reject)=>{if(!file)return reject(new Error('Upload a receipt image.'));const supported=['image/jpeg','image/png','image/webp'];if(!supported.includes(file.type))return reject(new Error('Use a JPG, PNG, or WebP receipt. For HEIC photos, take a screenshot first and upload the screenshot.'));if(file.size>8*1024*1024)return reject(new Error('Receipt image must be 8 MB or smaller.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read receipt.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('This receipt image cannot be opened. Please upload a screenshot in JPG or PNG format.'));image.onload=()=>{try{const max=1800,scale=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight)),w=Math.max(1,Math.round(image.naturalWidth*scale)),h=Math.max(1,Math.round(image.naturalHeight*scale)),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.drawImage(image,0,0,w,h);resolve(canvas.toDataURL('image/jpeg',.88))}catch(error){reject(new Error('Could not prepare the receipt image.'))}};image.src=reader.result};reader.readAsDataURL(file)})}
function safeImageData(value){return typeof value==='string'&&/^data:image\/(jpeg|png|webp);base64,/i.test(value)}
function orderImageUrl(orderId,kind){return `/api/orders/${encodeURIComponent(orderId)}/${kind}?token=${encodeURIComponent(state.token)}`}
function currentOrderValidation(){const amount=Math.floor(Number($('#robux-amount')?.value||0)),receipt=Boolean($('#receipt')?.files?.[0]),issues=[];if(!state.robloxUser)issues.push('Verify the ordering Roblox account');if(!Number.isFinite(amount)||amount<Number(state.config.minRobux)||amount>Number(state.config.maxRobux))issues.push(`Enter ${num(state.config.minRobux)}–${num(state.config.maxRobux)} Robux`);if(['covered_tax','not_covered_tax'].includes(state.method)){const required=state.method==='covered_tax'?Math.ceil(amount/0.7):amount,total=state.gamepasses.reduce((s,p)=>s+Number(p.price||0),0);if(!state.gamepasses.length)issues.push('Verify at least one gamepass');else if(total!==required)issues.push(`Gamepass total must equal R$ ${num(required)}`)}if(state.method==='gifting'){captureGiftItems();if(!state.giftRecipientUser)issues.push('Verify the gift recipient username');if(!state.giftItems.length||state.giftItems.some(x=>String(x.name||'').trim().length<2))issues.push('Enter every gift item name');if(!state.game)issues.push('Verify the Roblox game')}if(!receipt)issues.push('Upload the payment receipt');return issues}
function updateSubmitState(){const btn=$('#submit-order'),box=$('#checkout-readiness');if(!btn)return;const issues=currentOrderValidation();btn.disabled=issues.length>0;btn.textContent=issues.length?'Complete Required Details':'Submit Secure Order';if(box)box.innerHTML=issues.length?`<div class="readiness pending"><b>Complete before submitting</b><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<div class="readiness ready"><b>✓ Ready to submit</b><span>All required information has been verified.</span></div>`}

async function submitOrder(e){e.preventDefault();const btn=$('#submit-order'),issues=currentOrderValidation();if(issues.length){updateSubmitState();return toast(issues[0],'error')}btn.disabled=true;btn.textContent='Creating secure transaction…';try{const {amount}=calculate(),receiptData=await fileData($('#receipt').files[0]),paymentMethod=document.querySelector('[name=payment]:checked').value;if(state.method==='gifting')captureGiftItems();const giftingDetails=state.method==='gifting'?{recipientUsername:state.giftRecipientUser.name,recipientUser:state.giftRecipientUser,items:state.giftItems.map(x=>({name:String(x.name||'').trim(),quantity:Math.max(1,Number(x.quantity||1)),itemLink:String(x.itemLink||'').trim()})),instructions:$('#gift-notes')?.value.trim()}:null;const result=await api('/api/orders',{method:'POST',body:JSON.stringify({method:state.method,robloxUser:state.robloxUser,robuxAmount:amount,gamepasses:state.gamepasses,game:state.game,giftingDetails,paymentMethod,receiptData})});await refreshCore();showTransactionSuccess(result.order);state.page='orders'}catch(err){toast(err.message,'error');btn.disabled=false;btn.textContent='Submit Secure Order'}}
function showTransactionSuccess(order){const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="card modal-box transaction-success"><div class="success-mark">✓</div><h2>Order submitted securely</h2><p>Save this Transaction ID. Use it whenever you contact support about this order.</p><div class="transaction-code"><small>Transaction ID</small><b>${esc(order.transactionId||order.orderNo)}</b><button id="copy-transaction" class="btn secondary">Copy ID</button></div><p class="muted">Order number: ${esc(order.orderNo)}</p><button id="view-my-order" class="btn">View My Orders</button></div>`;document.body.appendChild(modal);$('#copy-transaction').onclick=async()=>{await navigator.clipboard?.writeText(order.transactionId||order.orderNo);toast('Transaction ID copied.')};$('#view-my-order').onclick=()=>{modal.remove();renderPage()}}

function orderRows(){return state.orders.map(o=>`<tr><td><b>${esc(o.orderNo)}</b><br><small>${esc(o.transactionId||o.orderNo)}</small><br><small>${new Date(o.createdAt).toLocaleString()}</small></td><td>${esc(o.customerName||'')}<br>@${esc(o.robloxUser?.name||'')}</td><td>${methodName(o.method)}</td><td>R$ ${num(o.robuxAmount)}<br>${money(o.totalPhp)}</td><td><span class="badge ${esc(o.status)}">${esc(o.status)}</span><br><small>Receipt attached</small></td><td><button class="btn secondary" data-view-order="${o.id}">View</button></td></tr>`).join('')}
async function renderOrders(options={}){const silent=Boolean(options.silent);window.clearTimeout(state.ordersRetryTimer);if(!silent)shell(`<div class="orders-toolbar"><div><b>${state.user.role==='admin'?'Order Management':'Your Orders'}</b><p class="muted">Pull down on mobile or press Refresh to get the newest status.</p></div><button id="refresh-orders" class="btn secondary">↻ Refresh</button></div><div class="card"><div id="orders-content"><div class="orders-loading"><div class="skeleton" style="height:64px"></div><div class="skeleton" style="height:64px;margin-top:10px"></div><div class="skeleton" style="height:64px;margin-top:10px"></div></div></div></div>`,state.user.role==='admin'?'Manage Orders':'My Orders');try{state.ordersLoading=true;const refresh=$('#refresh-orders');if(refresh){refresh.disabled=true;refresh.textContent='Refreshing…'}const d=await api('/api/orders');state.orders=d.orders;const box=$('#orders-content');if(!box)return;box.innerHTML=`<div class="desktop-orders table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Method</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${orderRows()||'<tr><td colspan="6">No orders yet.</td></tr>'}</tbody></table></div><div class="mobile-orders">${state.orders.map(o=>`<article class="mobile-order-card"><div class="mobile-order-top"><div><b>${esc(o.orderNo)}</b><small>${esc(o.transactionId||o.orderNo)}</small><small>${new Date(o.createdAt).toLocaleString()}</small></div><span class="badge ${esc(o.status)}">${esc(o.status)}</span></div><div class="mobile-order-grid"><span><small>Customer</small>${esc(o.customerName||'')}<br>@${esc(o.robloxUser?.name||'')}</span><span><small>Method</small>${methodName(o.method)}</span><span><small>Robux</small>R$ ${num(o.robuxAmount)}</span><span><small>Payment</small>${money(o.totalPhp)}</span></div><button class="btn secondary" data-view-order="${o.id}">View Order</button></article>`).join('')||'<div class="muted">No orders yet.</div>'}</div>`;box.querySelectorAll('[data-view-order]').forEach(b=>b.onclick=()=>openOrder(b.dataset.viewOrder));installPullToRefresh()}catch(e){const box=$('#orders-content');if(box)box.innerHTML=`<div class="notice error"><b>Orders could not load.</b><p>${esc(e.message)}</p><button id="retry-orders" class="btn secondary">Try Again</button></div>`;$('#retry-orders')&&($('#retry-orders').onclick=()=>renderOrders());state.ordersRetryTimer=setTimeout(()=>{if(state.page==='orders'&&!state.ordersLoading)renderOrders({silent:true})},5000)}finally{state.ordersLoading=false;const refresh=$('#refresh-orders');if(refresh){refresh.disabled=false;refresh.textContent='↻ Refresh';refresh.onclick=()=>renderOrders()}}}
function installPullToRefresh(){if(window.rsrPullRefreshInstalled)return;window.rsrPullRefreshInstalled=true;let startY=0,tracking=false;document.addEventListener('touchstart',e=>{if(state.page!=='orders'||window.scrollY>2)return;startY=e.touches[0].clientY;tracking=true},{passive:true});document.addEventListener('touchend',e=>{if(!tracking)return;tracking=false;const endY=e.changedTouches[0].clientY;if(endY-startY>85&&!state.ordersLoading){toast('Refreshing orders…');renderOrders()}},{passive:true})}

async function openOrder(id){try{const d=await api(`/api/orders/${id}`);showOrder(d.order)}catch(e){toast(e.message,'error')}}
function showOrder(o){const admin=state.user.role==='admin',isPassOrder=['covered_tax','not_covered_tax'].includes(o.method),receiptOk=Boolean(o.hasReceipt||safeImageData(o.receiptData)),proofOk=Boolean(o.hasDeliveryProof||safeImageData(o.deliveryProof)),receiptUrl=orderImageUrl(o.id,'receipt'),proofUrl=orderImageUrl(o.id,'proof');const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="card modal-box order-modal"><div class="modal-head"><div><small class="muted">Order details</small><h2>${esc(o.orderNo)}</h2><div class="transaction-inline"><small>Transaction ID</small><b>${esc(o.transactionId||o.orderNo)}</b></div></div><button class="btn secondary" id="close-modal">Close</button></div><div class="order-detail-grid"><section class="order-facts"><p><b>Customer:</b> ${esc(o.customerName)} (${esc(o.customerEmail||'')})</p><p><b>Roblox:</b> @${esc(o.robloxUser?.name||'')} · ID ${esc(o.robloxUser?.id||'')}</p><p><b>Method:</b> ${methodName(o.method)}</p>${o.method==='gifting'?`<div class="gift-detail-box"><b>🎁 Gift details</b><p><span>Recipient:</span> @${esc(o.giftingDetails?.recipientUsername||o.robloxUser?.name||'')}</p><p><span>Item:</span> ${esc((o.giftingDetails?.items||[]).map(x=>`${x.name} × ${x.quantity}${x.itemLink?' · '+x.itemLink:''}`).join(', ')||o.giftingDetails?.itemName||'Not provided')}</p><p><span>Quantity:</span> ${num(o.giftingDetails?.quantity||1)}</p><p><span>Instructions:</span> ${esc(o.giftingDetails?.instructions||'No special instructions')}</p></div>`:''}${isPassOrder?`<div class="admin-gamepass-box"><div class="section-head"><div><b>🎟 Submitted Gamepasses</b><p class="muted">Admin must open and purchase these exact links.</p></div><span class="badge ${Number(o.gamepasses?.reduce((s,p)=>s+Number(p.price||0),0))===Number(o.requiredGamepass)?'Completed':'Cancelled'}">R$ ${num(o.gamepasses?.reduce((s,p)=>s+Number(p.price||0),0)||0)} / R$ ${num(o.requiredGamepass||0)}</span></div>${(o.gamepasses||[]).length?`<div class="admin-pass-list">${o.gamepasses.map((p,i)=>`<article class="admin-pass-item">${p.thumbnail?`<img src="${esc(p.thumbnail)}" alt="Gamepass">`:''}<div><small>Gamepass ${i+1}</small><b>${esc(p.name||'Roblox Gamepass')}</b><span>Creator: ${esc(p.creator||'Unknown')} · ID ${esc(p.id||'')}</span><code>${esc(p.url||'')}</code></div><strong>R$ ${num(p.price||0)}</strong><a class="btn success" href="${esc(p.url||'')}" target="_blank" rel="noopener">Open / Buy Gamepass</a></article>`).join('')}</div>`:'<div class="notice error">No gamepass links were submitted with this order.</div>'}</div>`:''}<p><b>Order:</b> R$ ${num(o.robuxAmount)} · ${money(o.totalPhp)}</p><p><b>Status:</b> <span class="badge ${esc(o.status)}">${esc(o.status)}</span></p><p><b>Admin message:</b> ${esc(o.adminNote||'No message yet.')}</p>${proofOk?`<div class="proof-box"><b>Delivery proof from admin</b><img class="receipt" src="${proofUrl}" alt="Delivery proof"></div>`:''}</section><section class="receipt-panel"><div class="receipt-head"><div><small class="muted">Payment evidence</small><b>Customer receipt</b></div>${receiptOk?`<a class="btn secondary" href="${receiptUrl}" target="_blank" rel="noopener">Open Full Receipt</a>`:''}</div>${receiptOk?`<img class="receipt receipt-preview" src="${receiptUrl}" alt="Customer payment receipt">`:`<div class="receipt-missing"><b>Receipt preview unavailable</b><p>The uploaded file is missing or uses an unsupported format. Ask the customer to upload a JPG or PNG screenshot.</p></div>`}</section></div>${o.method==='gifting'?`<div class="gifting-support-card"><div><b>🎁 Gifting Delivery Chat</b><p class="muted">Coordinate the game, joining time, private server, and delivery directly for this order.</p></div><button id="open-gifting-chat" class="btn">Open Gifting Chat</button></div>`:''}${admin?`<hr style="border-color:var(--line)"><div class="admin-order-actions"><div class="field"><label>Message to customer / cancellation reason</label><textarea id="admin-note" class="input" placeholder="Write a clear update for the customer">${esc(o.adminNote||'')}</textarea></div><div class="field"><label>Delivery proof image (used when completing)</label><input id="delivery-proof" class="input" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">JPG, PNG, or WebP. The customer can view this image in their order.</small></div><div class="simple-actions"><button class="btn success" data-action="complete" ${['Completed','Cancelled'].includes(o.status)?'disabled':''}>✓ Complete Order</button><button class="btn danger" data-action="cancel" ${['Completed','Cancelled'].includes(o.status)?'disabled':''}>✕ Cancel Order</button></div></div>`:''}</div>`;document.body.appendChild(modal);$('#close-modal').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};const giftingChat=$('#open-gifting-chat');if(giftingChat)giftingChat.onclick=()=>{state.chatOrderId=o.id;state.adminChatUserId=o.userId;state.page='chat';modal.remove();renderPage()};modal.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{let deliveryProof='';if(b.dataset.action==='complete'&&$('#delivery-proof')?.files?.[0])deliveryProof=await fileData($('#delivery-proof').files[0]);const note=$('#admin-note')?.value||'';if(b.dataset.action==='cancel'&&note.trim().length<5)throw new Error('Enter a clear cancellation reason.');if(!confirm(b.dataset.action==='complete'?'Mark this order as completed?':'Cancel this order?'))return;await api(`/api/admin/orders/${o.id}`,{method:'PATCH',body:JSON.stringify({action:b.dataset.action,adminNote:note,deliveryProof})});toast(b.dataset.action==='complete'?'Order completed.':'Order cancelled.');modal.remove();await refreshCore();renderOrders()}catch(e){toast(e.message,'error')}})}

async function renderChat(){window.clearInterval(window.chatTimer);shell(`<div class="card chat-card"><div id="chat-context"></div><div class="chat-layout">${state.user.role==='admin'?'<div class="chat-list" id="chat-list"></div>':''}<div class="chat-panel"><div class="messages" id="messages"><div class="skeleton" style="height:180px"></div></div><form id="chat-form" class="chat-compose"><textarea id="chat-text" class="input" rows="3" placeholder="Type a message…"></textarea><button id="chat-send" class="btn">Send</button></form></div></div></div>`,'Live Support');const input=$('#chat-text');input.value=localStorage.getItem(currentDraftKey())||'';input.addEventListener('input',saveChatDraft);input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit()}});$('#chat-form').onsubmit=sendChatMessage;await loadChatView(true);window.chatTimer=setInterval(()=>{if(state.page==='chat'&&!state.chatSending)loadChatView(false)},2200)}
function messageSignature(list){return list.map(m=>m.id).join('|')}
function chatMessagesHtml(visible){return visible.map(m=>`<div class="msg ${m.senderRole===state.user.role?'me':''}"><b>${esc(m.senderName)}</b>${m.orderId?'<span class="order-msg-tag">Gifting order</span>':''}<div class="msg-text">${esc(m.text)}</div><small>${new Date(m.createdAt).toLocaleTimeString()}</small></div>`).join('')||'<div class="muted">Start a conversation. Your unfinished message stays saved while new replies arrive.</div>'}
function currentDraftKey(){return `rsr_chat_draft_${state.user.id}_${state.chatOrderId||'general'}_${state.adminChatUserId||'self'}`}
function saveChatDraft(){const input=$('#chat-text');if(!input)return;localStorage.setItem(currentDraftKey(),input.value)}
function visibleChatMessages(){const admin=state.user.role==='admin';let visible=admin?state.messages.filter(m=>m.userId===state.adminChatUserId):state.messages;if(state.chatOrderId)visible=visible.filter(m=>m.orderId===state.chatOrderId);else visible=visible.filter(m=>!m.orderId);return visible}
async function fetchChatData(){const d=await api('/api/chat');state.messages=d.messages;const customers=d.customers||[];if(state.user.role==='admin'&&!state.adminChatUserId&&customers[0])state.adminChatUserId=customers[0].id;return customers}
async function loadChatView(initial=false){try{const input=$('#chat-text'),draft=input?.value??'',selection=input?{start:input.selectionStart,end:input.selectionEnd}:null,customers=await fetchChatData(),visible=visibleChatMessages(),messages=$('#messages'),context=$('#chat-context'),list=$('#chat-list');if(!messages)return;const order=state.chatOrderId?state.orders.find(o=>o.id===state.chatOrderId):null;if(context)context.innerHTML=order?`<div class="order-chat-context"><div><b>🎁 ${esc(order.transactionId||order.orderNo)} · Gifting Chat</b><p class="muted">Recipient @${esc(order.giftingDetails?.recipientUsername||'')} · ${esc((order.giftingDetails?.items||[]).map(x=>`${x.name} × ${x.quantity}`).join(', '))}</p></div><button id="leave-order-chat" class="btn secondary">All Support Messages</button></div>`:'';if($('#leave-order-chat'))$('#leave-order-chat').onclick=()=>{saveChatDraft();state.chatOrderId='';loadChatView(true)};if(list){list.innerHTML=customers.map(c=>`<button data-chat-user="${c.id}" class="${state.adminChatUserId===c.id?'active':''}">${esc(c.name)}<br><small>${esc(c.email)}</small></button>`).join('')||'<span class="muted">No customers yet.</span>';list.querySelectorAll('[data-chat-user]').forEach(b=>b.onclick=()=>{saveChatDraft();state.adminChatUserId=b.dataset.chatUser;state.chatOrderId='';const saved=localStorage.getItem(currentDraftKey())||'';input.value=saved;loadChatView(true)})}const sig=messageSignature(visible);if(initial||messages.dataset.signature!==sig){const nearBottom=messages.scrollHeight-messages.scrollTop-messages.clientHeight<100;messages.innerHTML=chatMessagesHtml(visible);messages.dataset.signature=sig;if(initial||nearBottom)messages.scrollTop=messages.scrollHeight}if(input){input.value=draft;requestAnimationFrame(()=>{input.setSelectionRange(selection?.start??draft.length,selection?.end??draft.length)})}}catch(e){if(initial)toast(e.message,'error')}}
async function sendChatMessage(e){e.preventDefault();const input=$('#chat-text'),text=input.value.trim();if(!text||state.chatSending)return;state.chatSending=true;const send=$('#chat-send');send.disabled=true;send.textContent='Sending…';try{await api('/api/chat',{method:'POST',body:JSON.stringify({text,userId:state.adminChatUserId,orderId:state.chatOrderId})});input.value='';localStorage.removeItem(currentDraftKey());await loadChatView(false)}catch(err){toast(err.message,'error')}finally{state.chatSending=false;send.disabled=false;send.textContent='Send';input.focus()}}

function renderTutorials(){shell(`<div class="market-hero compact"><div><small class="eyebrow">HELP CENTER</small><h2>Learn before you order</h2><p>Follow the official RSR Shop guides so your Roblox details and gamepasses are correct.</p></div></div><div class="grid grid-2 tutorial-grid">${tutorialCard('How to order',state.config.tutorials?.orderUrl,'Complete walkthrough from account verification to receipt upload.')}${tutorialCard('How to create a gamepass',state.config.tutorials?.gamepassUrl,'Create and price the correct gamepass for CT or NCT orders.')}</div><div class="card contact-center"><h2>Still need help?</h2><p class="muted">Contact support and include your Transaction ID for faster assistance.</p><div class="contact-actions"><a class="btn" href="${esc(contactFacebook())}" target="_blank" rel="noopener">Message on Facebook</a><a class="btn secondary" href="mailto:${esc(contactEmail())}">Email Support</a></div></div>`,'Tutorials')}
function renderNotifications(){const granted=typeof Notification!=='undefined'&&Notification.permission==='granted';const own=state.user.role==='admin'?state.orders:state.orders.filter(o=>o.userId===state.user.id);const recent=own.slice().sort((a,b)=>new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt)).slice(0,8);shell(`<div class="grid grid-2"><div class="card notification-card"><div class="notification-icon">🔔</div><h2>${granted?'Notifications enabled':'Enable notifications'}</h2><p class="muted">Receive order and support updates while RSR Shop is open or installed on your device.</p><button id="enable-notifications" class="btn" ${granted?'disabled':''}>${granted?'Enabled':'Enable Notifications'}</button><small class="muted">True background push while the app is fully closed requires a dedicated push service. This version provides fast browser/app alerts while active.</small></div><div class="card"><h2>Recent activity</h2><div class="activity-list">${recent.map(o=>`<button class="activity-item" data-open-order="${o.id}"><span class="badge ${esc(o.status)}">${esc(o.status)}</span><div><b>${esc(o.orderNo)}</b><small>${methodName(o.method)} · R$ ${num(o.robuxAmount)}</small></div><time>${new Date(o.updatedAt||o.createdAt).toLocaleString()}</time></button>`).join('')||'<p class="muted">No order activity yet.</p>'}</div></div></div>`,'Notifications');const b=$('#enable-notifications');if(b)b.onclick=enableNotifications;document.querySelectorAll('[data-open-order]').forEach(b=>b.onclick=()=>openOrder(b.dataset.openOrder))}
function renderProfile(){const own=state.orders.filter(o=>o.userId===state.user.id),completed=own.filter(o=>o.status==='Completed');shell(`<div class="profile-layout"><section class="card profile-main"><div class="profile-avatar">${esc((state.user.name||'R').charAt(0).toUpperCase())}</div><div><small class="eyebrow">${state.user.role==='admin'?'ADMIN ACCOUNT':'CUSTOMER ACCOUNT'}</small><h2>${esc(state.user.name)}</h2><p class="muted">${esc(state.user.email)}</p><span class="badge Completed">${esc(state.user.role)}</span></div></section><section class="grid grid-3 profile-stats"><div class="card stat"><span>Total orders</span><b>${num(own.length)}</b></div><div class="card stat"><span>Completed</span><b>${num(completed.length)}</b></div><div class="card stat"><span>Robux delivered</span><b>R$ ${num(completed.reduce((s,o)=>s+o.robuxAmount,0))}</b></div></section><section class="card"><h2>App preferences</h2><div class="profile-actions"><button data-theme-toggle class="btn secondary">Theme</button><button id="profile-notify" class="btn secondary">🔔 Notification Settings</button><button id="profile-install" class="btn secondary">📲 Install App</button></div></section><section class="card contact-center"><h2>Contact RSR Shop</h2><p class="muted">For payment, delivery, or order problems, include your Transaction ID.</p><div class="contact-details"><a href="${esc(contactFacebook())}" target="_blank" rel="noopener"><b>Facebook Support</b><span>${esc(contactFacebook())}</span></a><a href="mailto:${esc(contactEmail())}"><b>Email Support</b><span>${esc(contactEmail())}</span></a></div></section></div>`,'Profile');document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=()=>applyTheme(document.documentElement.dataset.theme==='light'?'dark':'light'));applyTheme(localStorage.getItem('rsr_theme')||'dark');$('#profile-notify').onclick=()=>{state.page='notifications';renderPage()};$('#profile-install').onclick=()=>{if(state.installPrompt){state.installPrompt.prompt()}else toast(/iphone|ipad|ipod/i.test(navigator.userAgent)?'Safari → Share → Add to Home Screen.':'Open your browser menu and choose Install App.')}}
function renderVouches(){shell(`<div class="grid grid-3">${state.vouches.map(v=>`<article class="card vouch"><div class="stars">${'★'.repeat(v.rating)}</div><h3>${esc(v.name)}</h3><small class="muted">@${esc(v.robloxUsername||'Verified customer')}</small><p>${esc(v.text)}</p></article>`).join('')}</div><div class="card" style="margin-top:16px"><h2>Submit your vouch</h2><form id="vouch-form" class="stack"><input id="vouch-username" class="input" placeholder="Roblox username"><select id="vouch-rating" class="input"><option value="5">5 stars</option><option value="4">4 stars</option><option value="3">3 stars</option></select><textarea id="vouch-text" class="input" placeholder="Share your experience"></textarea><button class="btn">Submit for Approval</button></form></div>`,'Legit & Vouches');$('#vouch-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/vouches',{method:'POST',body:JSON.stringify({robloxUsername:$('#vouch-username').value,rating:$('#vouch-rating').value,text:$('#vouch-text').value})});toast(d.message);$('#vouch-form').reset()}catch(err){toast(err.message,'error')}}}
async function renderAdminVouches(){shell('<div class="card" id="vouch-admin">Loading…</div>','Vouch Review');try{const d=await api('/api/admin/vouches');$('#vouch-admin').innerHTML=d.vouches.map(v=>`<div class="notice"><b>${esc(v.name)}</b> · ${'★'.repeat(v.rating)} · ${v.approved?'Approved':'Pending'}<p>${esc(v.text)}</p><button class="btn success" data-vouch="${v.id}" data-approved="true">Approve</button> <button class="btn danger" data-vouch="${v.id}" data-approved="false">Hide</button></div>`).join('')||'No vouches.';document.querySelectorAll('[data-vouch]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/vouches/${b.dataset.vouch}`,{method:'PATCH',body:JSON.stringify({approved:b.dataset.approved==='true'})});renderAdminVouches()})}catch(e){toast(e.message,'error')}}
function renderAnalytics(){const orders=state.orders,completed=orders.filter(o=>o.status==='Completed'),cancelled=orders.filter(o=>o.status==='Cancelled'),pending=orders.filter(o=>!['Completed','Cancelled'].includes(o.status)),revenue=completed.reduce((s,o)=>s+Number(o.totalPhp||0),0),robux=completed.reduce((s,o)=>s+Number(o.robuxAmount||0),0),byMethod=['covered_tax','not_covered_tax','instant_send','gifting'].map(method=>{const list=completed.filter(o=>o.method===method);return{method,count:list.length,revenue:list.reduce((s,o)=>s+Number(o.totalPhp||0),0),robux:list.reduce((s,o)=>s+Number(o.robuxAmount||0),0)}});const max=Math.max(1,...byMethod.map(x=>x.count));shell(`<div class="grid grid-4"><div class="card stat"><span class="muted">Completed orders</span><b>${num(completed.length)}</b></div><div class="card stat"><span class="muted">Active orders</span><b>${num(pending.length)}</b></div><div class="card stat"><span class="muted">Cancelled</span><b>${num(cancelled.length)}</b></div><div class="card stat"><span class="muted">Completed revenue</span><b>${money(revenue)}</b></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><h2>Sales by method</h2><div class="analytics-list">${byMethod.map(x=>`<div class="analytics-row"><div><b>${methodName(x.method)}</b><small>${num(x.count)} completed · R$ ${num(x.robux)}</small></div><div class="bar"><span style="width:${Math.max(4,x.count/max*100)}%"></span></div><strong>${money(x.revenue)}</strong></div>`).join('')}</div></div><div class="card"><h2>Business summary</h2><div class="summary-list"><p><span>Total delivered</span><b>R$ ${num(robux)}</b></p><p><span>Average completed order</span><b>${money(completed.length?revenue/completed.length:0)}</b></p><p><span>Completion rate</span><b>${orders.length?Math.round(completed.length/orders.length*100):0}%</b></p><p><span>Total customers</span><b>${num(new Set(orders.map(o=>o.userId)).size)}</b></p></div></div></div>`,'Analytics')}
async function renderSettings(){shell('<div class="card" id="settings-box">Loading settings…</div>','Shop Settings');try{const d=await api('/api/admin/settings');state.config=d.settings;const s=d.settings;$('#settings-box').innerHTML=`<form id="settings-form" class="stack"><div><h2>Robux rates</h2><p class="muted">Enter the PHP price for 1 Robux. The customer total updates automatically during checkout.</p><div class="grid grid-2">${[['covered_tax','🛡️ Covered Tax'],['not_covered_tax','🏷️ Not Covered Tax'],['instant_send','⚡ Instant Send'],['gifting','🎁 Gifting']].map(([id,label])=>`<div class="field"><label>${label} rate (PHP per 1 Robux)</label><input class="input rate-input" data-rate="${id}" type="number" min="0" step="0.01" value="${Number(s.rates[id]||0)}"><label class="toggle-row"><input type="checkbox" data-method-toggle="${id}" ${s.methods[id]?'checked':''}> Enable this method</label></div>`).join('')}</div></div><div><h2>Order limits</h2><div class="grid grid-2"><div class="field"><label>Minimum Robux</label><input id="set-min" class="input" type="number" min="1" value="${s.minRobux}"></div><div class="field"><label>Maximum Robux</label><input id="set-max" class="input" type="number" min="1" value="${s.maxRobux}"></div></div></div><div class="settings-section"><h2>Tutorial videos</h2><p class="muted">Paste a YouTube, Facebook, Google Drive, or other public video link. You can change these links anytime.</p><div class="grid grid-2"><div class="field"><label>How to order tutorial URL</label><input id="tutorial-order" class="input" type="url" placeholder="https://..." value="${esc(s.tutorials?.orderUrl||'')}"></div><div class="field"><label>How to create a gamepass tutorial URL</label><input id="tutorial-gamepass" class="input" type="url" placeholder="https://..." value="${esc(s.tutorials?.gamepassUrl||'')}"></div></div></div><div class="settings-section"><h2>Contact & marketplace information</h2><p class="muted">These details appear across the customer app, support, tutorials, and order pages.</p><div class="grid grid-2"><div class="field"><label>Facebook support page</label><input id="contact-facebook" class="input" type="url" value="${esc(s.facebookUrl||state.config.facebookUrl||contactFacebook())}"></div><div class="field"><label>Support email</label><input id="contact-email" class="input" type="email" value="${esc(s.contactEmail||state.config.contactEmail||contactEmail())}"></div></div><div class="field"><label>Announcement banner</label><input id="shop-announcement" class="input" value="${esc(s.announcement||'')}"></div></div><button class="btn" type="submit">Save Shop Settings</button></form>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();try{const rates={},methods={};document.querySelectorAll('[data-rate]').forEach(i=>rates[i.dataset.rate]=Number(i.value));document.querySelectorAll('[data-method-toggle]').forEach(i=>methods[i.dataset.methodToggle]=i.checked);const out=await api('/api/admin/settings',{method:'PATCH',body:JSON.stringify({rates,methods,minRobux:Number($('#set-min').value),maxRobux:Number($('#set-max').value),tutorials:{orderUrl:$('#tutorial-order').value.trim(),gamepassUrl:$('#tutorial-gamepass').value.trim()},facebookUrl:$('#contact-facebook').value.trim(),contactEmail:$('#contact-email').value.trim(),announcement:$('#shop-announcement').value.trim()})});state.config=out.settings;toast('Shop settings saved.')}catch(err){toast(err.message,'error')}}}catch(e){toast(e.message,'error')}}

function updateInstallButton(selector){const b=$(selector);if(!b)return;if(state.installPrompt){b.classList.remove('hidden');b.onclick=async()=>{state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;b.classList.add('hidden')}}else{b.onclick=()=>toast(/iphone|ipad|ipod/i.test(navigator.userAgent)?'On iPhone/iPad: Safari → Share → Add to Home Screen.':'Use your browser menu and choose Install App.')}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e;updateInstallButton('#install-auth');updateInstallButton('#install-main')});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(console.error));
applyTheme(localStorage.getItem('rsr_theme')||'dark');
(async function boot(){try{state.config=await api('/api/config');if(state.token){await enterApp()}else renderAuth()}catch(e){renderAuth(`Server unavailable: ${e.message}`)}})();


// V21 professional motion and PWA helpers (non-blocking enhancement layer)
(function initV21Enhancements(){
  const reduceMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function decorate(root=document){
    root.querySelectorAll?.('.card:not([data-animate])').forEach((el,i)=>{el.dataset.animate='';el.style.setProperty('--delay',`${Math.min(i*45,270)}ms`)});
    root.querySelectorAll?.('.btn:not([data-ripple])').forEach(btn=>{
      btn.dataset.ripple='';
      btn.addEventListener('pointerdown',e=>{
        if(reduceMotion()||btn.disabled)return;
        const r=btn.getBoundingClientRect(),dot=document.createElement('span');
        dot.className='ripple';dot.style.left=`${e.clientX-r.left}px`;dot.style.top=`${e.clientY-r.top}px`;
        dot.style.width=dot.style.height=`${Math.max(r.width,r.height)}px`;btn.appendChild(dot);setTimeout(()=>dot.remove(),700);
      });
    });
  }
  const observer=new MutationObserver(m=>{for(const x of m)for(const n of x.addedNodes)if(n.nodeType===1)decorate(n)});
  observer.observe(document.documentElement,{childList:true,subtree:true});decorate();
  const showNet=(online)=>{document.querySelector('.online-banner')?.remove();const b=document.createElement('div');b.className=`online-banner ${online?'online':''}`;b.textContent=online?'Back online — your shop is connected.':'You are offline — orders and chat need internet.';document.body.appendChild(b);setTimeout(()=>b.remove(),online?2600:5000)};
  window.addEventListener('online',()=>showNet(true));window.addEventListener('offline',()=>showNet(false));
  if(!navigator.onLine)setTimeout(()=>showNet(false),500);
  if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('controllerchange',()=>{if(sessionStorage.getItem('rsr_reloading'))return;sessionStorage.setItem('rsr_reloading','1');location.reload()});}
})();
